// spec/canon.ts
/**
 * Status: draft until the M06 exit. MILESTONES.md 1.5, D-179.
 * M06 is the first milestone that runs this file.
 */
// The two canon registries (D-095): mechanisms and archetypes. Equations are
// TypeScript derive() functions; the YAML seed equations become docs.
// Version 4, 2026-10-04. Carries D-014, D-075, D-095, D-096, D-097, D-098,
// D-164, D-165, D-177.
//
// Seeds as of 2026-10-04: 24 mechanisms (seed/mechanisms.seed.yaml, 11 of
// them id-only) and 29 archetypes (seed/circuits.seed.yaml). Counts are
// generated by tools/counts.mjs from M-1 onward.

import type { FaceFrame, Process, Qualification, ResistivityDirection, Tier } from "./ids.js";
import type { Feature, FeatureKind } from "./features.js";
import type { ReadModelKind } from "./circuit.js";
import type { BodyDraft, PartDraft } from "./build.js";
import type { Assertion, BuildWarning, Metric } from "./part-ir.js";
import type { CheckId } from "./checks.js";
import type { ProfileLookup } from "./profile.js";
import type { SchemaLike } from "./schema.js";
import type { MaterialSlot } from "./chase.js";

/**
 * One derived output with its unit and qualification: qualify() over the
 * tiers of the profile rows derive() read, so a resistance from an inferred
 * row is computed with basis inferred.
 */
export type DerivedValue = DerivedValueBase & Qualification;

interface DerivedValueBase {
  /** Value in `unit`. */
  readonly value: number;
  /** Unit, for example "mm", "N", "ratio", "deg". */
  readonly unit: string;
  /** The equation as text, for docs and hbf://mechanism/<id>. */
  readonly equation: string;
}

/**
 * Status values of the two registries (M06 card, "Status values used in
 * both registries"; CANONS.md 1.3). typed and proven run derive() and
 * apply(); stub, candidate and unproven are registered and refused with
 * E_REF naming statusReason. Widened at M06-T01 from the D-097 pair.
 */
export type MechanismStatus = "typed" | "stub" | "candidate" | "unproven";
export type ArchetypeStatus = "proven" | "stub" | "candidate" | "unproven";

/**
 * The canonical original an entry ports from (D-222, the M06 originals
 * rule): a file under fab-knowledge/originals/<slug>/, the function or
 * lines its MECHANISMS.md or CANONS.md section 11 row names, and the
 * sha256 that equals its lineage.json row and orig/<slug>/SHA256SUMS.
 */
export interface CanonOriginal {
  /** Design slug, the directory under originals/, for example "knurl". */
  readonly slug: string;
  /** Path inside originals/<slug>/, for example "files/knurl.html". */
  readonly file: string;
  /** Function or block named by the row, for example "K.layout". */
  readonly fn?: string;
  /** Source lines as the row cites them, for example "588 to 599". */
  readonly lines?: string;
  /** sha256 of the file bytes, lowercase hex. */
  readonly sha256: string;
  /** Record sections that say how the original makes it, for example "knurl 5.2". */
  readonly record: string;
}

export interface MechanismDef<P extends Readonly<Record<string, number>> = Readonly<Record<string, number>>> {
  /** Registry id, lowercase slug, for example "geneva-external". */
  readonly id: string;
  readonly version: string;
  readonly family: string;
  /** Degrees of freedom, count; null where the seed and the source are silent (CANONS.md 1.5). */
  readonly dof: number | null;
  /** Parameter schema; every field states its unit. */
  readonly params: SchemaLike<unknown, P>;
  /**
   * Pure. Geneva external, for example: dwell (n + 2)/(2n), index
   * (n - 2)/(2n), alpha 180 - 360/n deg (D-096).
   */
  derive(p: P, profile: ProfileLookup): Readonly<Record<string, DerivedValue>>;
  readonly governs: readonly string[];
  readonly failureModes: readonly string[];
  readonly processes: readonly Process[];
  /** Seed provenance line, for example "TUMBLER 2026-08, KNURL 2026-09". */
  readonly provenance: string;
  /** Reference ids proving this entry. */
  readonly reference: readonly string[];
  /** stub: an id-only seed entry without equations yet (D-097); candidate and unproven per CANONS.md 1.3. */
  readonly status: MechanismStatus;
  /** Why a stub, candidate or unproven entry is refused, and the card that promotes it; the E_REF hint carries it. */
  readonly statusReason?: string;
  /** The canonical original first, then any further source the port reads (D-222). */
  readonly original?: readonly CanonOriginal[];
  /**
   * Pure, optional. Places the mechanism on a PartDraft (D-177): emits
   * primitive features of admitted kinds, the derived numbers as metrics
   * each gated by a check id (D-075), and the assertions that check them,
   * such as the identity assertion of displacement-coincidence-latch
   * (margin + overshoot = stroke/2 - camlift - lugTot, CHK-MOT-05). A
   * mechanism with a governing identity enters a build this way, never as
   * a feature kind. Called by Author.mech in build.ts. Stub entries have
   * no apply.
   */
  apply?(input: ApplyIn<P>): MechanismApplyOut;
}

/**
 * What MechanismDef.apply returns: declarations merged into the host
 * PartDraft, ids prefixed `<mechanism id>.<call index>.` as for
 * archetypes. Every metric names its gate; "informational" is refused here
 * because a mechanism's derived number exists to be checked.
 */
export interface MechanismApplyOut {
  readonly bodies: readonly BodyDraft[];
  readonly features: readonly Feature[];
  readonly metrics: readonly (Metric & { readonly gate: CheckId })[];
  readonly assertions: readonly Assertion[];
  /**
   * Non-fatal build facts the mechanism's own audit raised, for example the
   * TUMBLER plan audit (a hole thinner than 1.5 kerf fuses shut, M06-T02
   * step 4). Author.mech appends them to the build's warnings. Added at
   * M06-T02.
   */
  readonly warnings?: readonly BuildWarning[];
}

/**
 * What an archetype's apply() reads (D-165). It runs on a PartDraft before
 * kernel stage 1, never on a built Part, so the same call serves the kernel
 * merge of chase.applied, Author.arch() inside build.ts, and arch.apply.
 */
export interface ApplyIn<P> {
  /** The host part as build.ts declared it, before any applied entry merges. */
  readonly draft: PartDraft;
  /**
   * Placement in the part frame for this build: origin mm, outward normal,
   * in-face u. Resolved by the kernel from a FaceRef on every build, so
   * apply() never sees a stale frame.
   */
  readonly face: FaceFrame;
  /** Validated and default-filled params. */
  readonly params: P;
  readonly profile: ProfileLookup;
}

/**
 * What apply() returns (D-165): declarations only, merged into the host
 * PartDraft by the kernel. No geometry, no check selection.
 *
 * Slot numbers in `slots` and in `bodies[].slot` are local to this result,
 * 1-based. The merge maps each local slot to the chase material slot with
 * the same material and role, and arch.apply appends any missing one to
 * chase.materials in the same patch (a PETG lid gains cTPU and cPLA slots
 * for a dome button). Body and feature ids are local too; the merge
 * prefixes them with `<archetype id>.<applied index>.`.
 */
export interface ApplyOut {
  /** Bodies the archetype adds (a dome button's cTPU plug and cPLA pads). */
  readonly bodies: readonly BodyDraft[];
  /** Features emitted, of kinds admitted at the kernel's milestone (D-059, D-177). Host-body features name `body`. */
  readonly features: readonly Feature[];
  /** Local ids of the emitted port features, each carrying a read model (D-078). */
  readonly ports: readonly string[];
  /** Material slots the bodies need, matched by material and role. */
  readonly slots: readonly MaterialSlot[];
  /**
   * The archetype's readouts for this placement (D-049): its fits rows and
   * feel readouts as informational metrics, and any number a check gates,
   * such as the click spring's FE curve under CHK-KEY-04. The merge and
   * Author.arch prefix the ids as they prefix feature ids. Added at M06-T08.
   */
  readonly metrics?: readonly Metric[];
  /** Non-fatal build facts, such as a fits row that is not ok; appended to the build's warnings. Added at M06-T08. */
  readonly warnings?: readonly BuildWarning[];
}

/**
 * A declared conductor path of an archetype (D-098, M06-T07 step 3): the
 * section, its length and the profile row it reads. resistances(profile)
 * obtains the row through ProfileLookup.resistivity() and calls profile
 * sectionResistance(row, lengthMm, widthMm x thicknessMm); no archetype
 * stores a resistance number. Computed at the archetype's defaults.
 */
export interface ConductorSection {
  /** Path id, for example "switch.cap" or "track". */
  readonly id: string;
  /** Profile material id, for example "cpla", "ctpu". */
  readonly material: string;
  readonly direction: ResistivityDirection;
  /** Section width across the current, mm; for a round post, the side of the equal-area square. */
  readonly widthMm: number;
  /** Section thickness across the current, mm. */
  readonly thicknessMm: number;
  /** Path length along the current, mm. */
  readonly lengthMm: number;
  /** Identical sections in series, count; absent means 1. */
  readonly series?: number;
  /** Where the section and its length come from: the original's file and line, or the seed row. */
  readonly source: string;
}

export interface ArchetypeDef<P extends Readonly<Record<string, unknown>> = Readonly<Record<string, unknown>>> {
  /** Registry id, lowercase slug, for example "force-comb", "printed-rotary-pot". */
  readonly id: string;
  readonly version: string;
  /**
   * The process families of the seed, then the kinds of entry CANONS.md
   * 11.3 registers from the originals (M06-T14, D-222): checks, kernels,
   * read models, firmware, tools, coupons, constraints, constructions,
   * systems and design rules, refused until their owning package ports them.
   */
  readonly family: "printed" | "copper" | "board" | "printed-or-copper"
    | "check" | "constraint" | "construction" | "coupon" | "design-rule" | "firmware" | "kernel" | "read-model" | "system" | "tool";
  /** Read channels used, count; null where the count is set by params (per board pin, per used pad). */
  readonly channels: number | null;
  /** What it senses, for example "touch", "angle", "force". */
  readonly senses: readonly string[];
  readonly emits: readonly FeatureKind[];
  /** D-078 read model; "none" for seats, carriers, passive wires and boards that read nothing (CANONS.md 1.5). */
  readonly read: ReadModelKind | "none";
  readonly params: SchemaLike<unknown, P>;
  /**
   * Resistances computed at load from profile resistivity and the declared
   * section (D-098), so one coupon updates every archetype and its tier.
   */
  derive(p: P, profile: ProfileLookup): Readonly<Record<string, DerivedValue>>;
  /**
   * Pure. Places the archetype on a face of a PartDraft (D-165). Called by
   * the kernel merge of chase.applied before stage 1, by Author.arch() in
   * build.ts, and by arch.apply to report what it would emit.
   */
  apply(input: ApplyIn<P>): ApplyOut;
  readonly limits: readonly string[];
  readonly tier: Tier;
  readonly provenance: string;
  readonly reference: readonly string[];
  /** candidate: FEELER THINPOT printed archetypes admitted at M06 for STYLUS (D-097, D-164); stub per CANONS.md 1.5. */
  readonly status: ArchetypeStatus;
  /** Why a stub, candidate or unproven entry is refused, and the card that promotes it; the E_REF hint carries it. */
  readonly statusReason?: string;
  /** The canonical original first, then any further source the port reads (D-222). */
  readonly original?: readonly CanonOriginal[];
  /**
   * Declared conductor paths at the defaults (D-098, M06-T07 step 3). The
   * registry computes their resistances and the archetype's tier from the
   * profile at load; absent or empty means the entry reads no resistivity row.
   */
  readonly sections?: readonly ConductorSection[];
}
